-- Advisory owner alerts for unusually large sales, generated by the existing
-- daily notification cron. This never blocks or changes a sale.
BEGIN;

CREATE FUNCTION public.generate_unusual_sale_notifications()
RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE inserted_count integer;
BEGIN
  WITH candidates AS (
    SELECT s.id, s.organization_id, s.total, s.invoice_number, b.sample_size, b.median_total
    FROM public.sales s
    CROSS JOIN LATERAL (
      SELECT count(*) AS sample_size,
        percentile_cont(0.5) WITHIN GROUP (ORDER BY previous.total) AS median_total
      FROM (
        SELECT prior.total FROM public.sales prior
        WHERE prior.organization_id = s.organization_id
          AND prior.created_at < s.created_at
          AND prior.created_at >= s.created_at - interval '90 days'
          AND prior.status = 'completed'
          AND NOT EXISTS (SELECT 1 FROM public.financial_reversals r WHERE r.sale_id = prior.id AND r.kind IN ('void','refund','return'))
        ORDER BY prior.created_at DESC LIMIT 30
      ) previous
    ) b
    WHERE s.created_at >= now() - interval '2 days'
      AND s.status = 'completed'
      AND NOT EXISTS (SELECT 1 FROM public.financial_reversals r WHERE r.sale_id = s.id AND r.kind IN ('void','refund','return'))
      AND b.sample_size >= 10
      AND s.total >= greatest(50000, b.median_total * 5)
  )
  INSERT INTO public.notifications
    (organization_id,user_id,recipient_role,type,title,message,body,severity,entity_type,entity_id,dedupe_key,data)
  SELECT c.organization_id,u.id,'business_owner','sale_anomaly','Review unusually large sale',
    format('Sale %s for NGN %s is much larger than recent sales. Review it if unexpected.',c.invoice_number,c.total),
    format('Sale %s for NGN %s is much larger than recent sales. Review it if unexpected.',c.invoice_number,c.total),
    'warning','sale',c.id,'sale-anomaly:'||c.id||':'||u.id,
    jsonb_build_object('sale_id',c.id,'amount',c.total,'comparison_sales',c.sample_size,'median_amount',c.median_total)
  FROM candidates c JOIN public.users u ON u.organization_id=c.organization_id
    AND u.role='business_owner' AND u.status='active'
  ON CONFLICT (organization_id,dedupe_key) WHERE dedupe_key IS NOT NULL DO NOTHING;
  GET DIAGNOSTICS inserted_count = ROW_COUNT;
  RETURN inserted_count;
END $$;
REVOKE ALL ON FUNCTION public.generate_unusual_sale_notifications() FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.generate_unusual_sale_notifications() TO service_role;

COMMIT;
